private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_nexus_core_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_capture_parse() != 10624) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_core_version() != 62792) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_fsrs_preview() != 52366) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_fsrs_review() != 45396) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_maths_check() != 1330) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_tutor_beats() != 51600) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_tutor_check_step() != 25175) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_tutor_read_reply() != 58435) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_tutor_speakable() != 53521) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_tutor_steps_prompt() != 39499) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_tutor_summarize_steps() != 60456) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_func_tutor_system_prompt() != 51894) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_method_replyreader_end() != 3940) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_method_replyreader_problems() != 27969) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_method_replyreader_push() != 34425) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_method_replyreader_sentences() != 28382) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nexus_core_ffi_checksum_constructor_replyreader_new() != 29446) {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureNexusCoreFfiInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

